server {
    listen 8080;
    server_name localhost;

    # Document root
    root /var/www/html;
    index index.html;

    # Custom access log with benchmark format
    access_log /var/log/nginx/benchmark-access.log benchmark;

    # Custom error log
    error_log /var/log/nginx/benchmark-error.log;

    # Apply rate limiting: 10 req/s with burst of 10
    limit_req zone=benchmark_limit burst=10;

    # Custom 404 error page
    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }

    location = /404.html {
        internal;
    }
}

